						for(EntityPlayer player : nearbyPlayers) if(HbmPlayerProps.getData(player).reputation <= -10) { matches = true; break; }
						if(!matches) continue;
					}

					if(recipe.extra == recipe.extra.GOOD_KARMA) {
						boolean matches = false;
						for(EntityPlayer player : nearbyPlayers) if(HbmPlayerProps.getData(player).reputation >= 10) { matches = true; break; }
