		if(meta >= 12) {
			this.setBlockBounds(0.0F, 2 * f, 0.0F, 1.0F, 14 * f, 1.0F);
		} else if(meta >= 8) {
			this.setBlockBounds(2 * f, 0.0F, 0.0F, 14 * f, 1.0F, 1.0F);
		} else if(meta >= 4) {
