import com.hbm.blocks.generic.BlockScaffold;
import com.hbm.main.ResourceManager;
import com.hbm.render.loader.HFRWavefrontObject;
import com.hbm.render.util.ObjUtil;

import net.minecraftforge.fml.client.registry.ISimpleBlockRenderingHandler;
import net.minecraft.block.Block;
import net.minecraft.client.renderer.RenderBlocks;
import net.minecraft.client.renderer.Tessellator;
import com.hbm.render.icon.IIcon;
import net.minecraft.world.IBlockAccess;

public class RenderScaffoldBlock implements ISimpleBlockRenderingHandler {

	@Override
	public void renderInventoryBlock(Block block, int metadata, int modelId, RenderBlocks renderer) {

		GL11.glPushMatrix();
		Tessellator tessellator = Tessellator.instance;
		IIcon iicon = block.getIcon(0, metadata);
		tessellator.setColorOpaque_F(1, 1, 1);

		if(renderer.hasOverrideBlockTexture()) {
			iicon = renderer.overrideBlockTexture;
		}

		GL11.glTranslated(0, -0.5, 0);
		tessellator.startDrawingQuads();
		ObjUtil.renderWithIcon((HFRWavefrontObject) ResourceManager.scaffold, iicon, tessellator, 0, false);
		tessellator.draw();

		GL11.glPopMatrix();
	}

	@Override
	public boolean renderWorldBlock(IBlockAccess world, int x, int y, int z, Block block, int modelId, RenderBlocks renderer) {

		Tessellator tessellator = Tessellator.instance;
		IIcon iicon = block.getIcon(0, world.getBlockMetadata(x, y, z));

		tessellator.setBrightness(block.getMixedBrightnessForBlock(world, x, y, z));
		tessellator.setColorOpaque_F(1, 1, 1);

		if(renderer.hasOverrideBlockTexture()) {
			iicon = renderer.overrideBlockTexture;
		}

		float ox = x + 0.5F;
		float oy = y;
		float oz = z + 0.5F;

		float rotation = (float) Math.PI * -0.5F;
		float pitch = 0;

		int meta = world.getBlockMetadata(x, y, z);

		if(meta >= 12) {
			pitch = (float) Math.PI * 0.5F;
			rotation = (float) -Math.PI;
			ox = x + 1.0F;
			oy = y + 0.5F;
		} else if(meta >= 8) {
			rotation = (float) -Math.PI;
		} else if(meta >= 4) {
			pitch = (float) Math.PI * 0.5F;
			oy = y + 0.5F;
			oz = z;
		}

		tessellator.addTranslation(ox, oy, oz);
		ObjUtil.renderWithIcon((HFRWavefrontObject) ResourceManager.scaffold, iicon, tessellator, rotation, pitch, true);
		tessellator.addTranslation(-ox, -oy, -oz);

		return true;
	}

	@Override
	public boolean shouldRender3DInInventory(int modelId) {
		return true;
	}

	@Override
	public int getRenderId() {
		return BlockScaffold.renderIDScaffold;
	}

